	Pipeline   string `json:"pipeline"`
	Status     string `json:"status"`
	StartedAt  string `json:"started_at"`
	DurationMs int64  `json:"duration_ms"`
	Mode       string `json:"mode"`
}

type HistoryOutput struct {
	Runs  []HistoryRun `json:"runs"`
	Count int          `json:"count"`
}

func saveRunRecord(record *RunRecord) error {
	dir := filepath.Join(".mlpipe", "runs")
	if err := os.MkdirAll(dir, 0755); err != nil {
		return err
	}
	path := filepath.Join(dir, fmt.Sprintf("%s.json", record.RunID))
	data, err := json.MarshalIndent(record, "", "  ")
	if err != nil {
		return err
	}
	return os.WriteFile(path, data, 0644)
}

func buildRunRecord(executor *Executor, startedAt time.Time, finishedAt time.Time, status string, run interface{}) *RunRecord {
	mode := "standard"
	var cvFolds *int
	if executor != nil && executor.cvFolds > 0 {
		mode = "cv"
		f := executor.cvFolds
		cvFolds = &f
	} else if executor != nil {
		// keep standard mode
	}

	skipped := []string{}
	if executor != nil {
		for _, name := range executor.skipStages {
			skipped = append(skipped, name)
		}
	}
	if len(skipped) == 0 {
		skipped = []string{}
	}

	summary := map[string]StageSummary{}
	if executor != nil {
		for name, r := range executor.results {
			if r == nil {
				continue
			}
			summary[name] = StageSummary{
				Status:     r.Status,
				CacheHit:   r.CacheHit,
				DurationMs: r.DurationMs,
			}
		}
	}

	var cacheStats *CacheStats
	if executor != nil {
		if executor.noCache {
			cacheStats = nil
		} else {
			cacheStats = executor.cacheStats
			if cacheStats == nil {
				cacheStats = &CacheStats{}
			}
		}
	}

	return &RunRecord{
		RunID:        strconv.FormatInt(finishedAt.UnixNano()/int64(time.Millisecond), 10),
		Pipeline:     executor.config.Pipeline.Name,
		StartedAt:    startedAt.UTC().Format(time.RFC3339),
		FinishedAt:   finishedAt.UTC().Format(time.RFC3339),
		DurationMs:   finishedAt.Sub(startedAt).Milliseconds(),
		Status:       status,
		Mode:         mode,
		CvFolds:      cvFolds,
		NoCache:      executor.noCache,
		SkippedStages: skipped,
		StageSummary: summary,
		CacheStats:   cacheStats,
	}
}

func cmdHistory(args []string) {
	var pipelineFilter string
	var statusFilter string
	limit := -1

	for i := 0; i < len(args); i++ {
		arg := args[i]
		switch {
		case arg == "--pipeline":
			if i+1 >= len(args) {
				printError("--pipeline requires a value")
				return
			}
			pipelineFilter = args[i+1]
			i++
		case strings.HasPrefix(arg, "--pipeline="):
			pipelineFilter = strings.TrimPrefix(arg, "--pipeline=")
		case arg == "--status":
			if i+1 >= len(args) {
				printError("--status requires a value")
				return
			}
			statusFilter = args[i+1]
			i++
		case strings.HasPrefix(arg, "--status="):
			statusFilter = strings.TrimPrefix(arg, "--status=")
		case arg == "--limit":
			if i+1 >= len(args) {
				printError("--limit requires a value")
				return
			}
			n, err := strconv.Atoi(args[i+1])
			if err != nil {
				printError("--limit requires an integer")
				return
			}
			limit = n
			i++
		case strings.HasPrefix(arg, "--limit="):
			n, err := strconv.Atoi(strings.TrimPrefix(arg, "--limit="))
			if err != nil {
				printError("--limit requires an integer")
				return
			}
			limit = n
		default:
			printError(fmt.Sprintf("unknown flag: %s", arg))
			return
		}
	}

	if statusFilter != "" && statusFilter != "success" && statusFilter != "failed" {
		printError("--status must be success or failed")
		return
	}

	runs, err := loadHistory()
	if err != nil {
		printError(err.Error())
		return
	}

	filtered := make([]HistoryRun, 0, len(runs))
	for _, r := range runs {
		if pipelineFilter != "" && r.Pipeline != pipelineFilter {
			continue
		}
		if statusFilter != "" && r.Status != statusFilter {
			continue
		}
		filtered = append(filtered, r)
	}

	sort.Slice(filtered, func(i, j int) bool {
		return filtered[i].RunID > filtered[j].RunID
	})

	if limit >= 0 && len(filtered) > limit {
		filtered = filtered[:limit]
	}

	printJSON(HistoryOutput{Runs: filtered, Count: len(filtered)})
}

func loadHistory() ([]HistoryRun, error) {
	dir := filepath.Join(".mlpipe", "runs")
	entries, err := os.ReadDir(dir)
	if err != nil {
		if os.IsNotExist(err) {
			return []HistoryRun{}, nil
		}
		return nil, err
	}
	runs := []HistoryRun{}
	for _, entry := range entries {
		if entry.IsDir() {
			continue
		}
		name := entry.Name()
		if !strings.HasSuffix(name, ".json") {
			continue
		}
		path := filepath.Join(dir, name)
		data, err := os.ReadFile(path)
		if err != nil {
			return nil, err
		}
		var r RunRecord
		if err := json.Unmarshal(data, &r); err != nil {
			return nil, err
		}
		runs = append(runs, HistoryRun{
			RunID:      r.RunID,
			Pipeline:   r.Pipeline,
			Status:     r.Status,
			StartedAt:  r.StartedAt,
			DurationMs: r.DurationMs,
			Mode:       r.Mode,
		})
	}
	return runs, nil
}
