import (
    "reflect"
    "sort"
)

type StageDiff struct {
    TypeChanged    *FieldDiff           `json:"type_changed,omitempty"`
    ParamsChanged  map[string]FieldDiff `json:"params_changed,omitempty"`
    DepsChanged    *ListDiff            `json:"deps_changed,omitempty"`
    InputsChanged  map[string]FieldDiff `json:"inputs_changed,omitempty"`
}

type FieldDiff struct {
    Old interface{} `json:"old"`
    New interface{} `json:"new"`
}

type ListDiff struct {
    Old []string `json:"old"`
    New []string `json:"new"`
}

type ConfigDiff struct {
    PipelineName     *FieldDiff          `json:"pipeline_name,omitempty"`
    StagesAdded      []string            `json:"stages_added"`
    StagesRemoved    []string            `json:"stages_removed"`
    StagesModified   map[string]StageDiff `json:"stages_modified"`
    StagesUnchanged  []string            `json:"stages_unchanged"`
}

func cmdDiff(args []string) {
    if len(args) != 2 {
        printError("usage: mlpipe diff <config1.json> <config2.json>")
        return
    }
    config1, err := loadConfig(args[0])
    if err != nil {
        printError(err.Error())
        return
    }
    config2, err := loadConfig(args[1])
    if err != nil {
        printError(err.Error())
        return
    }
    printJSON(diffConfigs(config1, config2))
}

func diffConfigs(c1, c2 *Config) ConfigDiff {
    result := ConfigDiff{
        StagesAdded:     []string{},
        StagesRemoved:   []string{},
        StagesModified:  map[string]StageDiff{},
        StagesUnchanged: []string{},
    }

    if c1.Pipeline.Name != c2.Pipeline.Name {
        result.PipelineName = &FieldDiff{Old: c1.Pipeline.Name, New: c2.Pipeline.Name}
    }

    stages1 := map[string]StageConfig{}
    for _, s := range c1.Stages {
        stages1[s.Name] = s
    }
    stages2 := map[string]StageConfig{}
    for _, s := range c2.Stages {
        stages2[s.Name] = s
    }

    allNames := map[string]bool{}
    for name := range stages1 {
        allNames[name] = true
    }
    for name := range stages2 {
        allNames[name] = true
    }

    names := make([]string, 0, len(allNames))
    for name := range allNames {
        names = append(names, name)
    }
    sort.Strings(names)

    for _, name := range names {
        s1, ok1 := stages1[name]
        s2, ok2 := stages2[name]
        if !ok1 {
            result.StagesAdded = append(result.StagesAdded, name)
            continue
        }
        if !ok2 {
            result.StagesRemoved = append(result.StagesRemoved, name)
            continue
        }
        diff := diffStages(s1, s2)
        if diff == nil {
            result.StagesUnchanged = append(result.StagesUnchanged, name)
        } else {
            result.StagesModified[name] = *diff
        }
    }

    return result
}

func diffStages(s1, s2 StageConfig) *StageDiff {
    diff := StageDiff{
        ParamsChanged: map[string]FieldDiff{},
        InputsChanged: map[string]FieldDiff{},
    }
    changed := false

    if s1.Type != s2.Type {
        diff.TypeChanged = &FieldDiff{Old: s1.Type, New: s2.Type}
        changed = true
    }

    if !sameStringList(s1.DependsOn, s2.DependsOn) {
        diff.DepsChanged = &ListDiff{Old: s1.DependsOn, New: s2.DependsOn}
        changed = true
    }

    if !sameMap(s1.Params, s2.Params) {
        allKeys := map[string]bool{}
        for k := range s1.Params {
            allKeys[k] = true
        }
        for k := range s2.Params {
            allKeys[k] = true
        }
        keys := make([]string, 0, len(allKeys))
        for k := range allKeys {
            keys = append(keys, k)
        }
        sort.Strings(keys)
        for _, k := range keys {
            v1, ok1 := s1.Params[k]
            v2, ok2 := s2.Params[k]
            if ok1 && ok2 {
                if !reflect.DeepEqual(v1, v2) {
                    diff.ParamsChanged[k] = FieldDiff{Old: v1, New: v2}
                }
            } else if ok1 {
                diff.ParamsChanged[k] = FieldDiff{Old: v1, New: nil}
            } else {
                diff.ParamsChanged[k] = FieldDiff{Old: nil, New: v2}
            }
        }
        if len(diff.ParamsChanged) > 0 {
            changed = true
        } else {
            diff.ParamsChanged = nil
        }
    }

    if !sameMap(s1.Inputs, s2.Inputs) {
        allKeys := map[string]bool{}
        for k := range s1.Inputs {
            allKeys[k] = true
        }
        for k := range s2.Inputs {
            allKeys[k] = true
        }
        keys := make([]string, 0, len(allKeys))
        for k := range allKeys {
            keys = append(keys, k)
        }
        sort.Strings(keys)
        for _, k := range keys {
            v1, ok1 := s1.Inputs[k]
            v2, ok2 := s2.Inputs[k]
            if ok1 && ok2 {
                if !reflect.DeepEqual(v1, v2) {
                    diff.InputsChanged[k] = FieldDiff{Old: v1, New: v2}
                }
            } else if ok1 {
                diff.InputsChanged[k] = FieldDiff{Old: v1, New: nil}
            } else {
                diff.InputsChanged[k] = FieldDiff{Old: nil, New: v2}
            }
        }
        if len(diff.InputsChanged) > 0 {
            changed = true
        } else {
            diff.InputsChanged = nil
        }
    }

    if !changed {
        return nil
    }
    return &diff
}

func sameStringList(a, b []string) bool {
    if len(a) != len(b) {
        return false
    }
    for i := range a {
        if a[i] != b[i] {
            return false
        }
    }
    return true
}

func sameMap(a, b map[string]interface{}) bool {
    if len(a) != len(b) {
        return false
    }
    for k, v := range a {
        bv, ok := b[k]
        if !ok || !reflect.DeepEqual(v, bv) {
            return false
        }
    }
    return true
}
