)

type Dataset struct {
        Columns []string   `json:"columns"`
        Types   []string   `json:"types"`
        Rows    [][]string `json:"rows"`
}

func loadDataset(path string, schema map[string]interface{}) (*Dataset, error) {
        f, err := os.Open(path)
        if err != nil {
                if os.IsNotExist(err) {
                        return nil, fmt.Errorf("file not found: %s", path)
                }
                return nil, err
        }
        defer f.Close()

        r := csv.NewReader(f)
        records, err := r.ReadAll()
        if err != nil {
                return nil, err
        }
        if len(records) == 0 {
                return &Dataset{Columns: []string{}, Types: []string{}, Rows: [][]string{}}, nil
        }

        header := records[0]
        rows := records[1:]
        columns := header
        types := make([]string, len(columns))
        for i, col := range columns {
                if schemaType, ok := schema[col]; ok {
                        types[i] = fmt.Sprintf("%v", schemaType)
                } else {
                        types[i] = inferColumnType(rows, i)
                }
        }
        return &Dataset{Columns: columns, Types: types, Rows: rows}, nil
}

func inferColumnType(rows [][]string, idx int) string {
        for _, row := range rows {
                if idx >= len(row) {
                        continue
                }
                val := strings.TrimSpace(row[idx])
                if val == "" {
                        continue
                }
                if _, ok := parseFloat64(val); !ok {
                        return "categorical"
                }
        }
        return "numeric"
}

func parseFloat64(s string) (float64, bool) {
        s = strings.TrimSpace(s)
        if s == "" {
                return 0, false
        }
        f, err := strconv.ParseFloat(s, 64)
        if err != nil {
                return 0, false
        }
        return f, true
}

func formatFloat(f float64) string {
        if math.IsNaN(f) {
                return "NaN"
        }
        if math.IsInf(f, 1) {
                return "+Inf"
        }
        if math.IsInf(f, -1) {
                return "-Inf"
        }
        return strconv.FormatFloat(f, 'g', -1, 64)
}

